export const GetNodeByUriDocument = gql`
    query GetNodeByURI($uri: String!, $categoryName: String, $first: Int, $last: Int, $after: String, $before: String) {
  nodeByUri(uri: $uri) {
    __typename
    isContentNode
    isTermNode
    ... on Post {
      id
      title
      date
      uri
      excerpt
      slug
      categories {
        nodes {
          name
          uri
        }
      }
      featuredImage {
        node {
          srcSet
          sourceUrl
          altText
          caption
          title
          mediaDetails {
            height
            width
          }
        }
      }
      seo {
        ...PostTypeSEOMetadata
      }
      editorBlocks(flat: false) {
        ...WPBlocks
        ... on CoreMediaText {
          __typename
          clientId
          parentClientId
          attributes {
            mediaAlt
            mediaUrl
          }
          innerBlocks {
            ...WPBlocks
          }
        }
      }
      tags(where: {orderby: COUNT, hideEmpty: true}, first: 100) {
        __typename
        edges {
          node {
            ... on Tag {
              __typename
              id
              name
              slug
              uri
            }
          }
        }
      }
    }
    ... on Page {
      id
      title
      uri
      slug
      date
      content
      featuredImage {
        node {
          srcSet
          sourceUrl
          altText
          caption
          title
          mediaDetails {
            height
            width
          }
        }
      }
      seo {
        ...PostTypeSEOMetadata
      }
      editorBlocks(flat: false) {
        ...WPBlocks
        ... on CoreMediaText {
          __typename
          clientId
          parentClientId
          attributes {
            mediaAlt
            mediaUrl
          }
          innerBlocks {
            ...WPBlocks
          }
        }
      }
      homeContent {
        ...HomeContentFields
      }
    }
    ... on Category {
      id
      name
      posts(
        where: {status: PUBLISH, orderby: [{field: DATE, order: DESC}]}
        first: $first
        after: $after
        last: $last
        before: $before
      ) {
        edges {
          cursor
          node {
            ... on Post {
              date
              title
              excerpt
              uri
              slug
              categories {
                nodes {
                  name
                  uri
                }
              }
              featuredImage {
                node {
                  mediaDetails {
                    height
                    width
                  }
                  srcSet
                  sourceUrl
                  altText
                  caption
                  title
                }
              }
            }
          }
        }
        pageInfo {
          hasNextPage
          hasPreviousPage
          startCursor
          endCursor
        }
      }
      seo {
        ...TaxonomySEOMetadata
      }
    }
    ... on Tag {
      id
      name
      posts(
        where: {status: PUBLISH, orderby: [{field: DATE, order: DESC}]}
        first: 200
      ) {
        edges {
          cursor
          node {
            ... on Post {
              date
              title
              excerpt
              uri
              slug
              categories {
                nodes {
                  name
                  uri
                }
              }
              featuredImage {
                node {
                  srcSet
                  sourceUrl
                  altText
                  caption
                  title
                  mediaDetails {
                    height
                    width
                  }
                }
              }
            }
          }
        }
        pageInfo {
          hasNextPage
          hasPreviousPage
          startCursor
          endCursor
        }
      }
      seo {
        ...TaxonomySEOMetadata
      }
    }
  }
  posts(
    where: {status: PUBLISH, orderby: [{field: DATE, order: DESC}], categoryName: $categoryName}
    first: $first
    last: $last
    after: $after
    before: $before
  ) {
    __typename
    edges {
      cursor
      node {
        __typename
        ... on Post {
          id
          title
          date
          uri
          excerpt
          slug
          categories(first: 5) {
            edges {
              node {
                ... on Category {
                  __typename
                  id
                  name
                  slug
                }
              }
            }
          }
          tags {
            edges {
              node {
                ... on Tag {
                  id
                  name
                  slug
                  uri
                }
              }
            }
          }
        }
      }
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
  }
  ...GeneralSettings
}
    ${PostTypeSeoMetadataFragmentDoc}
${WpBlocksFragmentDoc}
${HomeContentFieldsFragmentDoc}
${TaxonomySeoMetadataFragmentDoc}
${GeneralSettingsFragmentDoc}`;
